<?php
defined('ABSPATH') || exit;

add_action('init', function () {
    add_shortcode('favers_cobra_shop', 'favers_cobra_storefront');
});

add_action('wp_enqueue_scripts', function () {
    $post = get_post();
    if (is_page('cobra') || ($post && has_shortcode($post->post_content, 'favers_cobra_shop'))) {
        wp_enqueue_style('favers-cobra-shop', plugins_url('../assets/storefront.css', __FILE__), array(), '1.2.0');
    }
});

/** Only replace an empty page or the exact catalog generated by v1.0. */
function favers_cobra_default_content($content) {
    if (is_admin() || !is_page('cobra') || !in_the_loop() || !is_main_query()) {
        return $content;
    }
    $plain = trim(preg_replace('/<!--.*?-->/s', '', $content));
    if ($plain === '' || $plain === '[products category="cobra" paginate="true" limit="12"]') {
        return '[favers_cobra_shop]';
    }
    return $content;
}
add_filter('the_content', 'favers_cobra_default_content', 8);

function favers_cobra_shop_options($input) {
    $read = function ($key) use ($input) {
        return isset($input[$key]) && is_string($input[$key]) ? sanitize_text_field(wp_unslash($input[$key])) : '';
    };
    $type = $read('cobra_type');
    $sort = $read('cobra_sort');
    return array(
        'type' => in_array($type, array('drivers', 'irons'), true) ? $type : 'all',
        'sort' => in_array($sort, array('newest', 'price-low', 'price-high'), true) ? $sort : 'newest',
        'search' => substr($read('cobra_search'), 0, 100),
    );
}

/** Scoped to a single WooCommerce shortcode invocation, never other catalogs. */
function favers_cobra_products($options) {
    $filter = function ($query) use ($options) {
        $type = $options['type'] === 'drivers' ? 'driver' : ($options['type'] === 'irons' ? 'iron' : '');
        // Title matching supports existing imports without changing categories.
        $search = trim($type . ' ' . $options['search']);
        if ($search !== '') {
            $query['s'] = $search;
            $query['search_columns'] = array('post_title');
        }
        return $query;
    };
    $empty = function () {
        echo '<div class="fc-empty"><span class="fc-eyebrow">THE NEXT ROUND STARTS HERE</span><h3>No clubs to show just yet.</h3><p>Try another search or check back as the collection grows.</p><a class="fc-text-link" href="' . esc_url(get_permalink()) . '#fc-collection">View all clubs &rarr;</a>';
        if (current_user_can('manage_woocommerce')) {
            echo '<p class="fc-admin-note">Store manager: import your supplier CSV, assign the Cobra category, and publish the products. Driver and iron filters match words in product titles.</p>';
        }
        echo '</div>';
    };
    add_filter('woocommerce_shortcode_products_query', $filter);
    add_action('woocommerce_shortcode_products_loop_no_results', $empty);
    $orderby = $options['sort'] === 'newest' ? 'date' : 'price';
    $order = $options['sort'] === 'price-low' ? 'ASC' : 'DESC';
    try {
        return do_shortcode('[products category="cobra" limit="12" columns="3" paginate="true" orderby="' . $orderby . '" order="' . $order . '"]');
    } finally {
        remove_filter('woocommerce_shortcode_products_query', $filter);
        remove_action('woocommerce_shortcode_products_loop_no_results', $empty);
    }
}

